import 'dart:convert';import 'package:shared_preferences/shared_preferences.dart';import '../models/app_models.dart';
class HistoryService{static const key='xai_desktop_history_v1';Future<List<HistoryItem>>load()async{final p=await SharedPreferences.getInstance();final raw=p.getString(key);if(raw==null)return[];return(jsonDecode(raw)as List).map((e)=>HistoryItem.fromJson(Map<String,dynamic>.from(e))).toList();}Future<void>save(List<HistoryItem>items)async{final p=await SharedPreferences.getInstance();await p.setString(key,jsonEncode(items.take(200).map((e)=>e.toJson()).toList()));}Future<void>clear()async{final p=await SharedPreferences.getInstance();await p.remove(key);}}
